window.VeilGardeData.files["Sources-VeilGardeInference"] = {"group":"Sources-VeilGardeInference","files":[{"path":"Sources/VeilGardeInference/Bundle/DetectorBundle.swift","status":"added","lang":"swift","hunks":[[1,0,1,58]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,8],"pin":[9,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":412,"scopes":[["S","DetectorBundle",null,"public",16,16,[16,50],58,null,-1,0,"a"],["i","init",["directory","manifest"],"public",20,20,[20,58],23,null,0,0,"a"],["v","shipped",null,"public static",26,26,[26,46],26,[25,25],0,8,"a"],["f","load",["_"],"public static",29,29,[29,71],35,[28,28],0,0,"a"],["f","url",["_","head"],"public",37,37,[37,73],39,null,0,0,"a"],["v","isShipped",null,"public",41,41,[41,31],41,null,0,8,"a"],["v","hashes",null,"public",44,44,[44,36],47,[43,43],0,0,"a"],["v","provenance",null,"public",51,51,[51,44],57,[49,50],0,0,"a"]],"old":"","new":"//\n//  DetectorBundle.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The set of artifacts one detection reads: the shipped bundle by default, or another\n//        hash-bound bundle directory (the flywheel's live bundle, a staged candidate) so the\n//        battery can judge exactly what promote would deploy.\n//  PIN:  A loaded bundle is verified (every artifact re-hashed against its manifest); the shipped\n//        one is verified once per process by ShippedBundle. Artifacts are resolved by role, never\n//        by file name, so a promoted head under a new name is found.\n//\n\nimport Foundation\n\npublic struct DetectorBundle: Sendable, Equatable {\n    public let directory: URL\n    public let manifest: BundleManifest\n\n    public init(directory: URL, manifest: BundleManifest) {\n        self.directory = directory\n        self.manifest = manifest\n    }\n\n    /// The bundle the package ships.\n    public static var shipped: DetectorBundle { DetectorBundle(directory: ShippedBundle.directory, manifest: ShippedBundle.manifest) }\n\n    /// A bundle directory, every artifact verified; one without a camera head or a combiner is refused.\n    public static func load(_ directory: URL) throws -> DetectorBundle {\n        let bundle = try ModelBundle.load(directory)\n        for role in [ArtifactRole.camera, .combiner] where bundle.manifest.artifact(role) == nil {\n            throw VeilGardeFailure.data(\"the bundle at \\(directory.path) has no \\(role.rawValue) artifact\", hint: \"a detector bundle holds a camera head and a stack combiner\")\n        }\n        return DetectorBundle(directory: bundle.root, manifest: bundle.manifest)\n    }\n\n    public func url(_ role: ArtifactRole, head: HeadKind? = nil) -> URL? {\n        manifest.artifact(role, head: head).map { directory.appendingPathComponent($0.file) }\n    }\n\n    public var isShipped: Bool { directory.standardizedFileURL == ShippedBundle.directory.standardizedFileURL }\n\n    /// The hashes a result reports: every artifact's by its slot, and the manifest's.\n    public var hashes: BundleHashes {\n        let manifestSHA = (try? JSONCoding.prettyEncoder().encode(manifest)).map { ContentHash.sha256Hex($0) } ?? \"\"\n        return BundleHashes(manifestSHA256: manifestSHA, artifacts: Dictionary(manifest.artifacts.map { ($0.slot, $0.sha256) }, uniquingKeysWith: { a, _ in a }))\n    }\n\n    /// What a report names to say which models it measured: the bundle's directory, the camera\n    /// head's and the combiner's hashes, and the manifest's hash.\n    public var provenance: [String: String] {\n        let h = hashes\n        var out = [\"bundle\": directory.path, \"manifest_sha256\": h.manifestSHA256]\n        if let c = manifest.artifact(.camera)?.sha256 { out[\"camera_sha256\"] = c }\n        if let c = manifest.artifact(.combiner)?.sha256 { out[\"combiner_sha256\"] = c }\n        return out\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Bundle/HeadRegistry.swift","status":"added","lang":"swift","hunks":[[1,0,1,42]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,7],"pin":[8,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":420,"scopes":[["C","HeadRegistry",null,"public final",16,16,[16,53],42,null,-1,0,"a"],["f","head",["_","in"],"public",22,22,[22,81],25,null,0,0,"a"],["f","combiner",["in"],"public",27,27,[27,70],30,null,0,0,"a"],["f","cached",["_","_","_"],"private",32,32,[32,108],41,null,0,0,"a"]],"old":"","new":"//\n//  HeadRegistry.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The linear heads and the stack combiner of a bundle, each read once per file and shared.\n//        A head the bundle does not name is nil, and the member it powers has nothing to say.\n//  PIN:  The reference's head and combiner caches, keyed by the artifact's path so two\n//        bundles in one process (the live bundle and a candidate under the battery) never mix,\n//        and by the file's modification date and size, so a file the flywheel rewrites in place\n//        (a promote, a restore) is read again.\n//\n\nimport Foundation\n\npublic final class HeadRegistry: @unchecked Sendable {\n    public static let shared = HeadRegistry()\n    private let lock = NSLock()\n    private var heads: [String: (FileStamp, LinearHead?)] = [:]\n    private var combiners: [String: (FileStamp, StackCombiner?)] = [:]\n\n    public func head(_ kind: HeadKind, in bundle: DetectorBundle) -> LinearHead? {\n        guard let url = bundle.url(.head, head: kind) else { return nil }\n        return cached(&heads, url) { try? LinearHead.load($0) }\n    }\n\n    public func combiner(in bundle: DetectorBundle) -> StackCombiner? {\n        guard let url = bundle.url(.combiner) else { return nil }\n        return cached(&combiners, url) { try? StackCombiner.load($0) }\n    }\n\n    private func cached<T>(_ store: inout [String: (FileStamp, T?)], _ url: URL, _ load: (URL) -> T?) -> T? {\n        let key = url.standardizedFileURL.path\n        let stamp = FileStamp(path: key)\n        lock.lock()\n        defer { lock.unlock() }\n        if let hit = store[key], hit.0 == stamp { return hit.1 }\n        let value = load(url)\n        store[key] = (stamp, value)\n        return value\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Bundle/ShippedBundle.swift","status":"added","lang":"swift","hunks":[[1,0,1,67]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,7],"pin":[8,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":424,"scopes":[["E","ShippedBundle",null,"public",16,16,[16,26],67,null,-1,0,"a",[]],["f","verified",[],"public static",40,40,[40,56],47,[39,39],0,0,"a"],["f","url",["_","head"],"public static",50,50,[50,79],55,[49,49],0,0,"a"],["f","registerWeightFolders",["workArea"],"public static",59,59,[59,87],66,[57,58],0,0,"a"]],"old":"","new":"//\n//  ShippedBundle.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The detector bundle this package ships: the artifacts it was verified with, bound by\n//        manifest.json. Everything that reads a shipped artifact asks here, by role.\n//  PIN:  The only file that writes `Bundle.module` (PackageLayeringTests). The bundle is verified\n//        once per process the first time it is used: every artifact re-hashed against the\n//        manifest, a mismatch refused. Its resource folder is registered with the WeightLocator,\n//        after the work area's weights/, for weights copied into the Inference resources.\n//\n\nimport Foundation\n\npublic enum ShippedBundle {\n    /// The folder holding manifest.json and the artifacts.\n    public static let directory: URL = {\n        let module = Bundle.module\n        for candidate in [module.resourceURL, module.bundleURL].compactMap({ $0 })\n        where FileManager.default.fileExists(atPath: candidate.appendingPathComponent(BundleManifest.fileName).path) {\n            return candidate\n        }\n        if let manifest = module.url(forResource: \"manifest\", withExtension: \"json\") { return manifest.deletingLastPathComponent() }\n        fatalError(\"VeilGardeInference's resource bundle has no manifest.json; rebuild the package\")\n    }()\n\n    private static let lock = NSLock()\n    nonisolated(unsafe) private static var verifiedBundle: ModelBundle?\n    nonisolated(unsafe) private static var registered = false\n\n    /// The manifest as shipped (not re-hashed).\n    public static let manifest: BundleManifest = {\n        do { return try JSONCoding.read(BundleManifest.self, from: directory.appendingPathComponent(BundleManifest.fileName)) } catch {\n            fatalError(\"the shipped manifest.json does not decode: \\(error)\")\n        }\n    }()\n\n    /// The shipped bundle, every artifact re-hashed once per process.\n    public static func verified() throws -> ModelBundle {\n        lock.lock()\n        defer { lock.unlock() }\n        if let verifiedBundle { return verifiedBundle }\n        let bundle = try ModelBundle.load(directory)\n        verifiedBundle = bundle\n        return bundle\n    }\n\n    /// The shipped artifact for a role; every role the detector reads is in the manifest.\n    public static func url(_ role: ArtifactRole, head: HeadKind? = nil) -> URL {\n        guard let artifact = manifest.artifact(role, head: head) else {\n            fatalError(\"the shipped bundle has no \\(head.map { \"head:\\($0.rawValue)\" } ?? role.rawValue)\")\n        }\n        return directory.appendingPathComponent(artifact.file)\n    }\n\n    /// Registers the weight folders: the work area's weights/ (when there is a work area), then\n    /// this bundle's resources. Idempotent.\n    public static func registerWeightFolders(workArea: WorkArea? = WorkArea.resolve()) {\n        lock.lock()\n        defer { lock.unlock() }\n        guard !registered else { return }\n        registered = true\n        if let workArea { WeightLocator.shared.register(workArea.weights) }\n        WeightLocator.shared.register(directory)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Config/InferenceConfig.swift","status":"added","lang":"swift","hunks":[[1,0,1,36]],"header":{"lines":[1,10],"target":"VeilGardeInference","what":[6,7],"pin":[8,9],"in":null,"out":null,"style":"swift"},"marks":[],"first":428,"scopes":[["S","InferenceConfig",null,"public",14,14,[14,40],36,null,-1,0,"a"],["i","init",["bundle","decision","dinoVariant","semanticResponsibility"],"public",25,25,[26,75],32,null,0,0,"a"],["v","shipped",null,"public static",35,35,[35,47],35,[34,34],0,8,"a"]],"old":"","new":"//\n//  InferenceConfig.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: How one detection runs: the bundle it reads, the camera member's operating point, the\n//        semantic backbone's size, and how much authority the semantic tiles have.\n//  PIN:  The defaults are the shipped detector's: the shipped bundle, 0.5 ± 0.04, DINOv2-small and\n//        the `.control` profile. The diagnostic and removed profiles are ablations.\n//\n\nimport Foundation\n\npublic struct InferenceConfig: Sendable {\n    /// The artifacts this detection reads (the shipped bundle unless told otherwise).\n    public var bundle: DetectorBundle\n    /// The camera member's operating point, 0.5 ± 0.04 (the screenshot member keeps its head's threshold with this band).\n    public var decision: DecisionRule\n    public var dinoVariant: DinoVariant\n    /// Production `.control`; the diagnostic and removed profiles are ablations.\n    public var semanticResponsibility: SemanticResponsibility\n    /// The frame seam's recursion guard; never set by callers.\n    public var skipFrameCheck: Bool\n\n    public init(bundle: DetectorBundle = .shipped, decision: DecisionRule = .camera, dinoVariant: DinoVariant = .small,\n                semanticResponsibility: SemanticResponsibility = .control) {\n        self.bundle = bundle\n        self.decision = decision\n        self.dinoVariant = dinoVariant\n        self.semanticResponsibility = semanticResponsibility\n        self.skipFrameCheck = false\n    }\n\n    /// The shipped defaults.\n    public static var shipped: InferenceConfig { InferenceConfig() }\n}\n"},{"path":"Sources/VeilGardeInference/Revisions/Combine.swift","status":"added","lang":"swift","hunks":[[1,0,1,56]],"header":{"lines":[1,16],"target":"VeilGardeInference","what":[6,11],"pin":[12,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":431,"scopes":[["S","Combine",null,"public",18,18,[18,32],56,null,-1,0,"a"],["i","init",[],"public",21,21,[21,18],21,null,0,8,"a"],["f","apply",["_","stack","signals","pipeline"],"public",23,23,[23,146],55,null,0,0,"a"]],"old":"","new":"//\n//  Combine.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The combiner revision, the first: it sets the verdict from the stack. It anchors on the\n//        screenshot member when the flat-UI gate fired and on the camera member otherwise, and\n//        takes the anchor's operating point. On an image with a present capture signature the\n//        anchor stands and the generated-side evidence is silenced (under the screenshot anchor,\n//        capped at P 0.10 and real). Otherwise the stack combiner pools the anchor with the\n//        evidence members its file names.\n//  PIN:  The pooled verdict is generated iff p > 0.5, with no inconclusive band. The evidence is\n//        read by name in the combiner file's order and summed in it. A bundle without a combiner,\n//        or a combiner naming a member the stack does not hold, is refused. Each evidence\n//        member's influence is StackCombiner.contribution.\n//\n\npublic struct Combine: Revision {\n    public let name = \"combiner\"\n\n    public init() {}\n\n    public func apply(_ v: inout WorkingVerdict, stack: [MemberOutput], signals s: DetectionSignals, pipeline: Pipeline) throws -> RevisionRecord {\n        guard let combiner = HeadRegistry.shared.combiner(in: s.config.bundle) else {\n            throw VeilGardeFailure.missing(\"the bundle has no stack combiner\")\n        }\n        let anchorName = s.gate.isScreenshot ? \"screenshot\" : \"camera\"\n        let anchor = try stack.required(anchorName, by: name)\n        guard let a = anchor.p else { throw VeilGardeFailure.missing(\"the \\(anchorName) member has no P(AI): the bundle has no \\(anchorName) head\") }\n        v.p = a\n        v.prediction = anchor.verdict\n        v.threshold = anchorName == \"screenshot\" ? (anchor.number(\"threshold\") ?? s.config.decision.threshold) : s.config.decision.threshold\n        v.band = s.config.decision.band\n\n        let capture = try stack.required(\"capture\", by: name)\n        if capture.flag(\"valid\") == true && capture.flag(\"present\") == true {\n            if anchorName == \"screenshot\" {\n                v.p = min(v.p, CaptureLaw.realCeiling)\n                v.prediction = \"real\"\n            }\n            return RevisionRecord(name: name, applied: true, p: v.p, prediction: v.prediction,\n                                  fields: [Field(\"anchor\", .text(anchorName)), Field(\"pooled\", .absent), Field(\"influence\", .absent)])\n        }\n        let evidence = try combiner.evidenceMembers.map { member -> Float in\n            guard let p = try stack.required(member, by: name).p else { throw VeilGardeFailure.missing(\"the \\(member) member has no P(AI)\") }\n            return p\n        }\n        let pooled = combiner.pool(anchor: a, evidence: evidence)\n        var influence: [String: Float] = [:]\n        for (k, member) in combiner.evidenceMembers.enumerated() { influence[member] = combiner.contribution(k, anchor: a, evidence: evidence) }\n        v.p = pooled\n        v.prediction = pooled > 0.5 ? \"generated\" : \"real\"\n        return RevisionRecord(name: name, applied: true, p: v.p, prediction: v.prediction,\n                              fields: [Field(\"anchor\", .text(anchorName)), Field(\"pooled\", .number(pooled)), Field(\"influence\", .map(influence))])\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Revisions/FrameSeam.swift","status":"added","lang":"swift","hunks":[[1,0,1,73]],"header":{"lines":[1,17],"target":"VeilGardeInference","what":[6,10],"pin":[11,16],"in":null,"out":null,"style":"swift"},"marks":[],"first":434,"scopes":[["S","FrameSeam",null,"public",22,22,[22,34],73,null,-1,0,"a"],["i","init",[],"public",25,25,[25,18],25,null,0,8,"a"],["f","apply",["_","stack","signals","pipeline"],"public",27,27,[27,146],45,null,0,0,"a"],["f","skipped",[],"",29,29,[29,41],32,null,2,4,"a"],["f","detectFrame",["_"],"static",48,48,[48,57],72,[47,47],0,0,"a"],["f","stats",["_","_"],"",55,55,[55,83],60,null,4,4,"a"],["f","qualifies",["_"],"",64,64,[64,62],64,null,4,12,"a"]],"old":"","new":"//\n//  FrameSeam.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The frame-seam revision (v3.3, live): a fake analog or film border drags the pooled\n//        evidence real-ward while the synthetic content hides inside. When the verdict is real,\n//        capture is absent and P ≥ 0.10, detect a uniform dark frame, run the whole pipeline once\n//        on a wide interior crop that keeps the frame-to-content seam, and take decisive interior\n//        evidence (interior ≥ 0.70 and at least 0.20 above P).\n//  PIN:  The frame detector, unchanged: a 96×96 luma grid, bands of 3% that qualify when dark\n//        (mean < 0.16), uniform (sd < 0.17) and darker than the interior by > 0.12, at least two\n//        qualifying sides, then the fixed rect (5%, 2%, 90%, 96%). The P ≥ 0.10 floor was\n//        re-validated 2026-07-19; real film scans read ≤ 0.01 under this rect (6 of 6). The crop\n//        is rendered as a fresh bitmap (renderCrop), never cropping(to:). The inner run's own\n//        frame seam is skipped (InferenceConfig.skipFrameCheck), so it recurses once.\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic struct FrameSeam: Revision {\n    public let name = \"frame-seam\"\n\n    public init() {}\n\n    public func apply(_ v: inout WorkingVerdict, stack: [MemberOutput], signals s: DetectionSignals, pipeline: Pipeline) throws -> RevisionRecord {\n        let present = stack.member(\"capture\")?.flag(\"present\") ?? false\n        func skipped() -> RevisionRecord {\n            RevisionRecord(name: name, applied: false, p: v.p, prediction: v.prediction,\n                           fields: [Field(\"interior_p\", .absent), Field(\"decisive\", .flag(false))])\n        }\n        guard !s.config.skipFrameCheck, v.prediction == \"real\", !present, v.p >= 0.10,\n              let interiorRect = Self.detectFrame(s.cgImage), let interior = ImageLoading.renderCrop(s.cgImage, interiorRect) else { return skipped() }\n        var cfg = s.config\n        cfg.skipFrameCheck = true\n        let pi = try pipeline.run(cgImage: interior, config: cfg).p\n        let decisive = pi >= 0.70 && (pi - v.p) >= 0.20\n        if decisive {\n            v.prediction = \"generated\"\n            v.p = pi\n        }\n        return RevisionRecord(name: name, applied: decisive, p: v.p, prediction: v.prediction,\n                              fields: [Field(\"interior_p\", .number(pi)), Field(\"decisive\", .flag(decisive))])\n    }\n\n    /// The interior rect when the image wears an analog or film frame, else nil.\n    static func detectFrame(_ image: CGImage) -> CGRect? {\n        let N = 96\n        var buf = [UInt8](repeating: 0, count: N * N)\n        guard let ctx = CGContext(data: &buf, width: N, height: N, bitsPerComponent: 8, bytesPerRow: N,\n                                  space: CGColorSpaceCreateDeviceGray(), bitmapInfo: CGImageAlphaInfo.none.rawValue) else { return nil }\n        ctx.interpolationQuality = .low\n        ctx.draw(image, in: CGRect(x: 0, y: 0, width: N, height: N))\n        func stats(_ xs: Range<Int>, _ ys: Range<Int>) -> (mean: Float, sd: Float) {\n            var s: Float = 0, s2: Float = 0, n: Float = 0\n            for y in ys { for x in xs { let v = Float(buf[y * N + x]) / 255; s += v; s2 += v * v; n += 1 } }\n            let m = s / max(n, 1)\n            return (m, max(0, s2 / max(n, 1) - m * m).squareRoot())\n        }\n        // CGContext.draw has a bottom-left origin: buffer row 0 is the IMAGE BOTTOM.\n        let b = Int(Float(N) * 0.03)\n        let interior = stats(b * 4 ..< N - b * 4, b * 4 ..< N - b * 4)\n        func qualifies(_ s: (mean: Float, sd: Float)) -> Bool { s.mean < 0.16 && s.sd < 0.17 && (interior.mean - s.mean) > 0.12 }\n        let imgTop = qualifies(stats(0 ..< N, N - b ..< N))\n        let imgBottom = qualifies(stats(0 ..< N, 0 ..< b))\n        let left = qualifies(stats(0 ..< b, 0 ..< N))\n        let right = qualifies(stats(N - b ..< N, 0 ..< N))\n        guard [imgTop, imgBottom, left, right].filter({ $0 }).count >= 2 else { return nil }\n        let W = CGFloat(image.width), H = CGFloat(image.height)\n        return CGRect(x: W * 0.05, y: H * 0.02, width: W * 0.90, height: H * 0.96)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Revisions/PreviewTail.swift","status":"added","lang":"swift","hunks":[[1,0,1,45]],"header":{"lines":[1,15],"target":"VeilGardeInference","what":[6,9],"pin":[10,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":441,"scopes":[["S","PreviewTail",null,"public",17,17,[17,36],45,null,-1,0,"a"],["i","init",[],"public",20,20,[20,18],20,null,0,8,"a"],["f","apply",["_","stack","signals","pipeline"],"public",22,22,[22,146],44,null,0,0,"a"]],"old":"","new":"//\n//  PreviewTail.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The preview-tail revision (v3.4, live): sub-512 images (capture invalid) are a\n//        physics-empty regime where the camera head learned \"small ⇒ AI\". When such an image reads\n//        generated with a clean semantic vote (majority ≤ 0.15), flip it to real only if the\n//        preview member reads ≤ 0.45 and the camera member's p_neutral reads ≤ 0.30.\n//  PIN:  A strict tail rescue, not a regime swap: OR-policies raised real false positives to\n//        20–27% and were rejected (the research record, 2026-07-17, quoted). The flip is committed\n//        only under the `.control` semantic profile (PublicSurface.project); the diagnostic profile\n//        records that it fired without moving the verdict, and without the semantic tiles it never\n//        arms.\n//\n\npublic struct PreviewTail: Revision {\n    public let name = \"preview-tail\"\n\n    public init() {}\n\n    public func apply(_ v: inout WorkingVerdict, stack: [MemberOutput], signals s: DetectionSignals, pipeline: Pipeline) throws -> RevisionRecord {\n        let valid = stack.member(\"capture\")?.flag(\"valid\") ?? false\n        let majority = stack.member(\"semantic-tiles\")?.number(\"majority\")\n        guard !valid, v.prediction == \"generated\", let m = majority, m <= 0.15 else {\n            return RevisionRecord(name: name, applied: false, p: v.p, prediction: v.prediction,\n                                  fields: [Field(\"majority\", majority.map { .number($0) } ?? .absent), Field(\"triggered\", .flag(false)), Field(\"fires\", .flag(false))])\n        }\n        let phv = stack.member(\"preview\")?.p ?? -1\n        let triggered = phv >= 0 && phv <= Specialist.previewCut\n        let pn = triggered ? stack.member(\"camera\")?.number(\"p_neutral\") : nil\n        let fires = triggered && (pn ?? 1.0) <= 0.30\n        var probeP = v.p, probeVerdict = v.prediction\n        if fires, let pn {\n            probeVerdict = \"real\"\n            probeP = min(probeP, pn)\n        }\n        let projection = PublicSurface.project(profile: s.config.semanticResponsibility, originalP: v.p, originalVerdict: v.prediction,\n                                               probeP: probeP, probeVerdict: probeVerdict, probeDecisive: fires)\n        v.p = projection.p\n        v.prediction = projection.verdict\n        return RevisionRecord(name: name, applied: projection.decisive, p: v.p, prediction: v.prediction,\n                              fields: [Field(\"majority\", .number(m)), Field(\"triggered\", .flag(triggered)), Field(\"fires\", .flag(fires))])\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Revisions/Revision.swift","status":"added","lang":"swift","hunks":[[1,0,1,71]],"header":{"lines":[1,20],"target":"VeilGardeInference","what":[6,15],"pin":[17,19],"in":null,"out":null,"style":"swift"},"marks":[],"first":444,"scopes":[["S","WorkingVerdict",null,"public",23,23,[23,50],35,[22,22],-1,0,"a"],["i","init",["p","prediction","threshold","band"],"public",29,29,[29,77],34,null,0,0,"a"],["P","Revision",null,"public",37,37,[37,35],42,null,-1,0,"a"],["v","name",null,"",39,39,[39,21],39,[38,38],2,9,"a"],["f","apply",["_","stack","signals","pipeline"],"",41,41,null,41,[40,40],2,1,"a"],["S","Revisions",null,"public",44,44,[44,34],50,null,-1,0,"a"],["i","init",[],"public",47,47,[47,66],49,null,5,0,"a"],["E","RevisionBuilder",null,"public",52,53,[53,28],61,null,-1,0,"a",[]],["f","buildExpression",["_"],"public static",54,54,[54,84],54,null,7,8,"a"],["f","buildExpression",["_"],"public static",55,55,[55,86],55,null,7,8,"a"],["f","buildBlock",["_"],"public static",56,56,[56,80],56,null,7,8,"a"],["f","buildOptional",["_"],"public static",57,57,[57,80],57,null,7,8,"a"],["f","buildEither",["first"],"public static",58,58,[58,81],58,null,7,8,"a"],["f","buildEither",["second"],"public static",59,59,[59,82],59,null,7,8,"a"],["f","buildArray",["_"],"public static",60,60,[60,79],60,null,7,8,"a"],["X","Array",null,"",63,63,[63,46],71,null,-1,0,"a"],["f","required",["_","by"],"",65,65,[65,78],70,[64,64],15,0,"a"]],"old":"","new":"//\n//  Revision.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The Revisions stage: after every member has spoken, the revisions read the stack's\n//        outputs in order and revise one working verdict, each recording what it did. The first\n//        sets the verdict (the combiner); the rest act only on decisive evidence (the frame seam,\n//        the preview tail). A new revision is one file that conforms to Revision and one line in\n//        a pipeline.\n//\n//            Revisions {\n//                Combine()\n//                FrameSeam()\n//            }\n//\n//  PIN:  Before the first revision the verdict is inconclusive at 0.5 under the config's rule; a\n//        pipeline without a revision that sets it says so. A revision reads members by name and\n//        refuses a stack that lacks one it needs.\n//\n\n/// The verdict as the revisions carry it.\npublic struct WorkingVerdict: Sendable, Equatable {\n    public var p: Float\n    public var prediction: String\n    public var threshold: Float\n    public var band: Float\n\n    public init(p: Float, prediction: String, threshold: Float, band: Float) {\n        self.p = p\n        self.prediction = prediction\n        self.threshold = threshold\n        self.band = band\n    }\n}\n\npublic protocol Revision: Sendable {\n    /// The revision's name in the result.\n    var name: String { get }\n    /// Revises the verdict from the stack's outputs and returns what it did.\n    func apply(_ verdict: inout WorkingVerdict, stack: [MemberOutput], signals: DetectionSignals, pipeline: Pipeline) throws -> RevisionRecord\n}\n\npublic struct Revisions: Sendable {\n    public let steps: [any Revision]\n\n    public init(@RevisionBuilder _ content: () -> [any Revision]) {\n        self.steps = content()\n    }\n}\n\n@resultBuilder\npublic enum RevisionBuilder {\n    public static func buildExpression(_ revision: some Revision) -> [any Revision] { [revision] }\n    public static func buildExpression(_ revisions: [any Revision]) -> [any Revision] { revisions }\n    public static func buildBlock(_ parts: [any Revision]...) -> [any Revision] { parts.flatMap { $0 } }\n    public static func buildOptional(_ part: [any Revision]?) -> [any Revision] { part ?? [] }\n    public static func buildEither(first part: [any Revision]) -> [any Revision] { part }\n    public static func buildEither(second part: [any Revision]) -> [any Revision] { part }\n    public static func buildArray(_ parts: [[any Revision]]) -> [any Revision] { parts.flatMap { $0 } }\n}\n\nextension Array where Element == MemberOutput {\n    /// The member a revision needs, or a failure naming it.\n    func required(_ name: String, by revision: String) throws -> MemberOutput {\n        guard let m = member(name) else {\n            throw VeilGardeFailure.data(\"the \\(revision) revision reads the \\(name) member, which the stack does not hold\")\n        }\n        return m\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Detector.swift","status":"added","lang":"swift","hunks":[[1,0,1,19]],"header":{"lines":[1,10],"target":"VeilGardeInference","what":[6,7],"pin":[8,9],"in":null,"out":null,"style":"swift"},"marks":[],"first":461,"scopes":[["E","Detector",null,"public",14,14,[14,21],19,null,-1,0,"a",[]],["f","detect",["cgImage","config","pipeline"],"public static",16,16,[16,136],18,[15,15],0,0,"a"]],"old":"","new":"//\n//  Detector.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The detector's one entry point: a decoded image through a pipeline, the shipped one\n//        unless told otherwise, into one result.\n//  PIN:  The command line, the battery, the census and the goldens all call this; none builds the\n//        stack itself.\n//\n\nimport CoreGraphics\n\npublic enum Detector {\n    /// The full result for one image.\n    public static func detect(cgImage: CGImage, config: InferenceConfig = .shipped, pipeline: Pipeline = .v1) throws -> InferenceResult {\n        try pipeline.run(cgImage: cgImage, config: config)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Signals.swift","status":"added","lang":"swift","hunks":[[1,0,1,66]],"header":{"lines":[1,15],"target":"VeilGardeInference","what":[6,11],"pin":[12,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":463,"scopes":[["C","DetectionSignals",null,"public final",20,20,[20,57],66,null,-1,0,"a"],["i","init",["cgImage","config"],"public",32,32,[32,59],38,null,0,0,"a"],["f","cached",["_","_"],"private",40,40,[40,121],47,null,0,0,"a"],["f","capture",[],"public",50,50,[50,44],50,[49,49],0,8,"a"],["f","dinoFusion",[],"public",53,53,[53,47],55,[52,52],0,0,"a"],["f","dinoNorm",[],"public",58,58,[58,45],60,[57,57],0,0,"a"],["f","patchTokens",[],"public",63,63,[63,82],65,[62,62],0,0,"a"]],"old":"","new":"//\n//  Signals.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The Shared Signals stage: what every member of the stack reads, computed once per image.\n//        The flat-UI screenshot gate (cheap, eager) and, on first use, the capture reading (the\n//        nine values and the signature, from one measurement), DINOv2's two CLS readings (the plain\n//        one the camera head reads, the force-resized one the linear heads read) and the plain\n//        input's 256 patch tokens the semantic tiles read. A new signal is one more cached reading\n//        here.\n//  PIN:  The normalized embedding is always the 360×640 force-resize, the plain one the 256/224\n//        preprocessing, both at the config's DINOv2 variant. Members never compute a signal\n//        themselves, so none is measured twice.\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic final class DetectionSignals: @unchecked Sendable {\n    public let cgImage: CGImage\n    public let config: InferenceConfig\n    public let gate: ScreenshotGate\n    public let width: Int\n    public let height: Int\n    private let lock = NSLock()\n    private var cachedCapture: CaptureReading?\n    private var cachedDinoNorm: [Float]?\n    private var cachedDinoFusion: [Float]?\n    private var cachedTokens: (values: [Float], count: Int, width: Int)?\n\n    public init(cgImage: CGImage, config: InferenceConfig) {\n        self.cgImage = cgImage\n        self.config = config\n        self.gate = ScreenshotLens.gate(cgImage)\n        self.width = cgImage.width\n        self.height = cgImage.height\n    }\n\n    private func cached<T>(_ slot: ReferenceWritableKeyPath<DetectionSignals, T?>, _ make: () throws -> T) rethrows -> T {\n        lock.lock()\n        defer { lock.unlock() }\n        if let value = self[keyPath: slot] { return value }\n        let value = try make()\n        self[keyPath: slot] = value\n        return value\n    }\n\n    /// The native-resolution capture measurement: the nine values and the signature.\n    public func capture() -> CaptureReading { cached(\\.cachedCapture) { CaptureLens.reading(cgImage) } }\n\n    /// The plain DINOv2 embedding the camera head reads.\n    public func dinoFusion() throws -> [Float] {\n        try cached(\\.cachedDinoFusion) { try SemanticLens.fusionEmbedding(cgImage, variant: config.dinoVariant) }\n    }\n\n    /// The 360×640 force-resized DINOv2 embedding the linear heads read.\n    public func dinoNorm() throws -> [Float] {\n        try cached(\\.cachedDinoNorm) { try SemanticLens.normalizedEmbedding(cgImage, variant: config.dinoVariant) }\n    }\n\n    /// The plain input's 256 patch tokens, row-major [count × width].\n    public func patchTokens() throws -> (values: [Float], count: Int, width: Int) {\n        try cached(\\.cachedTokens) { try SemanticLens.patchTokens(cgImage, variant: config.dinoVariant) }\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Stack/Members/Camera.swift","status":"added","lang":"swift","hunks":[[1,0,1,36]],"header":{"lines":[1,14],"target":"VeilGardeInference","what":[6,10],"pin":[11,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":470,"scopes":[["S","Camera",null,"public",16,16,[16,34],36,null,-1,0,"a"],["i","init",[],"public",19,19,[19,18],19,null,0,8,"a"],["f","score",["_"],"public",21,21,[21,69],35,null,0,0,"a"]],"old":"","new":"//\n//  Camera.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The camera member: the camera head, a booster over DINOv2's plain CLS embedding and the\n//        nine capture values (393 columns), the detector's take on whether a camera made the image.\n//        Its P(AI) is labelled at the config's operating point, 0.5 ± 0.04. It also reports\n//        p_neutral, the same head with the capture-validity shortcut neutralized, which the\n//        preview tail reads.\n//  PIN:  Column order is CameraRow's. Neutralizing sets valid = 1 and native px = max(·, 576):\n//        invalid-capture rows were 85.5% generated in the 2026-07-17 measurement and taught the\n//        head \"small ⇒ AI\". The head is scored with Frigate's evaluator from the config's bundle.\n//\n\npublic struct Camera: StackMember {\n    public let name = \"camera\"\n\n    public init() {}\n\n    public func score(_ s: DetectionSignals) throws -> MemberOutput? {\n        guard let url = s.config.bundle.url(.camera) else { throw VeilGardeFailure.missing(\"the bundle has no camera head\") }\n        let head = try TreeModelCache.shared.model(url)\n        guard head.numFeatures == CameraRow.width else {\n            throw VeilGardeFailure.data(\"the camera head reads \\(head.numFeatures) features; its row is \\(CameraRow.width) wide\")\n        }\n        let dino = try s.dinoFusion()\n        let capture = s.capture().features\n        let p = head.predict(CameraRow(dino: dino, capture: capture).asVector)\n        var neutral = capture.asVector\n        neutral[1] = 1.0\n        neutral[3] = max(neutral[3], 576.0)\n        let pNeutral = head.predict(dino + neutral)\n        return MemberOutput(name: name, p: p, verdict: s.config.decision.label(p), fields: [Field(\"p_neutral\", .number(pNeutral))])\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Stack/Members/Capture.swift","status":"added","lang":"swift","hunks":[[1,0,1,25]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,9],"pin":[10,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":473,"scopes":[["S","Capture",null,"public",14,14,[14,35],25,null,-1,0,"a"],["i","init",[],"public",17,17,[17,18],17,null,0,8,"a"],["f","score",["_"],"public",19,19,[19,69],24,null,0,0,"a"]],"old":"","new":"//\n//  Capture.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The capture member: the camera-capture signature as measured, the Nyquist peak a sensor's\n//        Bayer mosaic leaves, whether the image is large enough to read it, and whether it is\n//        present. It measures rather than scores, so it has no P(AI); a present signature is a\n//        real camera's, and the combiner silences the generated-side evidence on it.\n//  PIN:  valid needs a native short side of 512; present needs valid and peak ≥ 30. The verdict is\n//        \"real\" when present, \"absent\" when valid without the peak, \"invalid\" below 512.\n//\n\npublic struct Capture: StackMember {\n    public let name = \"capture\"\n\n    public init() {}\n\n    public func score(_ s: DetectionSignals) throws -> MemberOutput? {\n        let c = s.capture().signature\n        return MemberOutput(name: name, p: nil, verdict: c.valid && c.present ? \"real\" : (c.valid ? \"absent\" : \"invalid\"),\n                            fields: [Field(\"peak\", .number(c.peak)), Field(\"valid\", .flag(c.valid)),\n                                     Field(\"native_px\", .number(Float(c.nativePixels))), Field(\"present\", .flag(c.present))])\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Stack/Members/Screenshot.swift","status":"added","lang":"swift","hunks":[[1,0,1,35]],"header":{"lines":[1,14],"target":"VeilGardeInference","what":[6,9],"pin":[10,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":476,"scopes":[["S","Screenshot",null,"public",16,16,[16,38],35,null,-1,0,"a"],["i","init",[],"public",19,19,[19,18],19,null,0,8,"a"],["f","score",["_"],"public",21,21,[21,69],34,null,0,0,"a"]],"old":"","new":"//\n//  Screenshot.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The screenshot member: the flat-UI gate's three tells, whether they fire together, and the\n//        screenshot content head's P(AI) on the force-resized embedding, the take of a head\n//        trained on social-media screenshots, where the camera head false-positives. The combiner\n//        anchors on it when the gate fires.\n//  PIN:  The head's own threshold with the config's band labels its p; without a screenshot head in\n//        the bundle the member reports the gate with no p. The head must read the shared 360×640\n//        embedding (every shipped head does); one of another size is refused rather than fed the\n//        wrong reading.\n//\n\npublic struct Screenshot: StackMember {\n    public let name = \"screenshot\"\n\n    public init() {}\n\n    public func score(_ s: DetectionSignals) throws -> MemberOutput? {\n        let gate: [Field] = [Field(\"gate\", .flag(s.gate.isScreenshot)), Field(\"grad_zero\", .number(s.gate.gradZero)),\n                             Field(\"flat_strict\", .number(s.gate.flatStrict)), Field(\"top_color\", .number(s.gate.topColor))]\n        guard let head = HeadRegistry.shared.head(.screenshot, in: s.config.bundle) else {\n            return MemberOutput(name: name, p: nil, verdict: \"absent\", fields: gate)\n        }\n        guard head.normW == 360, head.normH == 640 else {\n            throw VeilGardeFailure.data(\"the screenshot head reads a \\(head.normW)×\\(head.normH) embedding; the shared signals hold the 360×640 one\")\n        }\n        let p = head.pAI(try s.dinoNorm())\n        let t = head.threshold\n        let verdict = abs(p - t) < s.config.decision.band ? \"inconclusive\" : (p > t ? \"generated\" : \"real\")\n        return MemberOutput(name: name, p: p, verdict: verdict, fields: gate + [Field(\"threshold\", .number(t))])\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Stack/Members/SemanticTiles.swift","status":"added","lang":"swift","hunks":[[1,0,1,35]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,8],"pin":[9,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":479,"scopes":[["S","SemanticTiles",null,"public",14,14,[14,41],35,null,-1,0,"a"],["i","init",[],"public",17,17,[17,18],17,null,0,8,"a"],["f","score",["_"],"public",19,19,[19,69],34,null,0,0,"a"]],"old":"","new":"//\n//  SemanticTiles.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The semantic-tiles member: the per-patch-token linear head on DINOv2's 16×16 token grid,\n//        P(generated) per token, and the fraction of tokens above 0.5, the semantic majority. Its\n//        p is the majority; the preview tail reads it, and the battery reads the grid.\n//  PIN:  Tokens of the PLAIN 256/224 input (no force-resize), head p > 0.5 counted. No entry when\n//        the bundle has no semtile head or the profile removes the semantic tiles, checked before\n//        any token is computed (no ViT forward).\n//\n\npublic struct SemanticTiles: StackMember {\n    public let name = \"semantic-tiles\"\n\n    public init() {}\n\n    public func score(_ s: DetectionSignals) throws -> MemberOutput? {\n        guard s.config.semanticResponsibility != .semanticRemoved, let head = HeadRegistry.shared.head(.semtile, in: s.config.bundle),\n              let toks = try? s.patchTokens() else { return nil }\n        let n = toks.count, d = toks.width\n        let side = Int(Double(n).squareRoot())\n        var grid = [[Float]](repeating: [Float](repeating: 0, count: side), count: side)\n        var gen = 0\n        for t in 0..<n {\n            let p = head.pAI(Array(toks.values[(t * d)..<((t + 1) * d)]))\n            grid[t / side][t % side] = p\n            if p > 0.5 { gen += 1 }\n        }\n        let majority = Float(gen) / Float(n)\n        return MemberOutput(name: name, p: majority, verdict: majority > 0.5 ? \"generated\" : \"real\",\n                            fields: [Field(\"majority\", .number(majority)), Field(\"grid\", .grid(grid))])\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Stack/Members/Specialist.swift","status":"added","lang":"swift","hunks":[[1,0,1,34]],"header":{"lines":[1,14],"target":"VeilGardeInference","what":[6,10],"pin":[11,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":482,"scopes":[["S","Specialist",null,"public",16,16,[16,38],34,null,-1,0,"a"],["v","name",null,"public",21,21,[21,28],21,null,0,8,"a"],["i","init",["_"],"public",23,23,[23,34],26,null,0,0,"a"],["f","score",["_"],"public",28,28,[28,69],33,null,0,0,"a"]],"old":"","new":"//\n//  Specialist.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A specialist member: one linear head on the force-resized DINOv2 embedding, a take on\n//        one sector of images. art (AI art against museum and human art), blur (generative blur\n//        against optical blur), human (photoreal AI people against real portraits), preview\n//        (small previews, where the camera head learned \"small ⇒ AI\"). One file serves every\n//        such head; a new one is a head file in the bundle and one line in the pipeline.\n//  PIN:  P(AI) is the head's; art, blur and human say generated above the head's threshold, preview\n//        reads real at or below 0.45, the preview tail's cut. A head the bundle lacks leaves no\n//        entry. The screenshot and semantic-tile heads have members of their own.\n//\n\npublic struct Specialist: StackMember {\n    /// The preview head's cut: at or below it the preview member reads real.\n    public static let previewCut: Float = 0.45\n\n    public let kind: HeadKind\n    public var name: String { kind.rawValue }\n\n    public init(_ kind: HeadKind) {\n        precondition(kind != .screenshot && kind != .semtile, \"the \\(kind.rawValue) head has a member of its own\")\n        self.kind = kind\n    }\n\n    public func score(_ s: DetectionSignals) throws -> MemberOutput? {\n        guard let head = HeadRegistry.shared.head(kind, in: s.config.bundle) else { return nil }\n        let p = head.pAI(try s.dinoNorm())\n        let verdict = kind == .preview ? (p <= Self.previewCut ? \"real\" : \"generated\") : (p > head.threshold ? \"generated\" : \"real\")\n        return MemberOutput(name: name, p: p, verdict: verdict)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Stack/Pipeline.swift","status":"added","lang":"swift","hunks":[[1,0,1,73]],"header":{"lines":[1,15],"target":"VeilGardeInference","what":[6,9],"pin":[10,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":486,"scopes":[["S","Pipeline",null,"public",19,19,[19,33],68,null,-1,0,"a"],["i","init",["stack","revisions"],"public",23,23,[23,52],26,null,0,0,"a"],["i","init",[],"public",28,28,[28,70],32,null,0,0,"a"],["v","v1",null,"public static",35,35,[35,35],53,[34,34],0,0,"a"],["f","run",["cgImage","config"],"public",56,56,[56,89],67,[55,55],0,0,"a"],["E","PipelineBuilder",null,"public",70,71,[71,28],73,null,-1,0,"a",[]],["f","buildBlock",["_","_"],"public static",72,72,[72,96],72,null,5,8,"a"]],"old":"","new":"//\n//  Pipeline.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The detector as one declaration: Decode → Shared Signals → Stack → Revisions → Result.\n//        The caller decodes; the pipeline computes the signals once, runs every member of its\n//        stack, runs its revisions in order, and returns one result that lists every member's\n//        output and every revision's record. `Pipeline.v1` is the shipped detector.\n//  PIN:  Stacking, not blending: each member keeps its own score in the result, and the combiner\n//        pools only the evidence members it names around one anchor; a monolithic combiner\n//        regressed real false positives 8% → 50–92% in the research's measurement, the stack\n//        holds them at 0%. Routing is never by image size. The training recipe declares the\n//        trainable members the same way (TrainingRecipe).\n//\n\nimport CoreGraphics\n\npublic struct Pipeline: Sendable {\n    public let stack: Stack\n    public let revisions: Revisions\n\n    public init(stack: Stack, revisions: Revisions) {\n        self.stack = stack\n        self.revisions = revisions\n    }\n\n    public init(@PipelineBuilder _ content: () -> (Stack, Revisions)) {\n        let parts = content()\n        self.stack = parts.0\n        self.revisions = parts.1\n    }\n\n    /// The shipped detector, v1.\n    public static var v1: Pipeline {\n        Pipeline {\n            Stack {\n                Screenshot()\n                Camera()\n                Capture()\n                Specialist(.art)\n                Specialist(.blur)\n                Specialist(.human)\n                Specialist(.preview)\n                SemanticTiles()\n            }\n            Revisions {\n                Combine()\n                FrameSeam()\n                PreviewTail()\n            }\n        }\n    }\n\n    /// Shared Signals → Stack → Revisions → Result, for one decoded image.\n    public func run(cgImage: CGImage, config: InferenceConfig) throws -> InferenceResult {\n        let signals = DetectionSignals(cgImage: cgImage, config: config)\n        let outputs = try stack.score(signals)\n        var verdict = WorkingVerdict(p: 0.5, prediction: \"inconclusive\", threshold: config.decision.threshold, band: config.decision.band)\n        var records: [RevisionRecord] = []\n        for revision in revisions.steps {\n            records.append(try revision.apply(&verdict, stack: outputs, signals: signals, pipeline: self))\n        }\n        return InferenceResult(prediction: verdict.prediction, p: verdict.p, threshold: verdict.threshold, band: verdict.band,\n                               imageWidth: signals.width, imageHeight: signals.height, stack: outputs, revisions: records,\n                               bundle: config.bundle.hashes)\n    }\n}\n\n@resultBuilder\npublic enum PipelineBuilder {\n    public static func buildBlock(_ stack: Stack, _ revisions: Revisions) -> (Stack, Revisions) { (stack, revisions) }\n}\n"},{"path":"Sources/VeilGardeInference/Stack/Stack.swift","status":"added","lang":"swift","hunks":[[1,0,1,50]],"header":{"lines":[1,19],"target":"VeilGardeInference","what":[6,14],"pin":[16,18],"in":null,"out":null,"style":"swift"},"marks":[],"first":493,"scopes":[["P","StackMember",null,"public",21,21,[21,38],26,null,-1,0,"a"],["v","name",null,"",23,23,[23,21],23,[22,22],0,9,"a"],["f","score",["_"],"",25,25,null,25,[24,24],0,1,"a"],["S","Stack",null,"public",28,28,[28,30],39,null,-1,0,"a"],["i","init",[],"public",31,31,[31,66],33,null,3,0,"a"],["f","score",["_"],"public",36,36,[36,70],38,[35,35],3,0,"a"],["E","StackBuilder",null,"public",41,42,[42,25],50,null,-1,0,"a",[]],["f","buildExpression",["_"],"public static",43,43,[43,88],43,null,6,8,"a"],["f","buildExpression",["_"],"public static",44,44,[44,90],44,null,6,8,"a"],["f","buildBlock",["_"],"public static",45,45,[45,86],45,null,6,8,"a"],["f","buildOptional",["_"],"public static",46,46,[46,86],46,null,6,8,"a"],["f","buildEither",["first"],"public static",47,47,[47,87],47,null,6,8,"a"],["f","buildEither",["second"],"public static",48,48,[48,88],48,null,6,8,"a"],["f","buildArray",["_"],"public static",49,49,[49,85],49,null,6,8,"a"]],"old":"","new":"//\n//  Stack.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The Stack stage: a flat list of members, each an independent take on the image. A member\n//        reads only the shared signals and says what it sees in its own output: its P(AI), its\n//        verdict, its own fields. No member reads another's output; that is the Revisions stage's\n//        job. A new member is one file that conforms to StackMember and one line in a pipeline.\n//\n//            Stack {\n//                Camera()\n//                Specialist(.art)\n//            }\n//\n//  PIN:  Members run in the declared order and the result lists them in it. A member that has\n//        nothing to say for this bundle or profile (its head is not in the bundle, the profile\n//        removed it) returns nil and has no entry.\n//\n\npublic protocol StackMember: Sendable {\n    /// The member's name in the result.\n    var name: String { get }\n    /// What the member sees in the image, or nil when it has nothing to say.\n    func score(_ s: DetectionSignals) throws -> MemberOutput?\n}\n\npublic struct Stack: Sendable {\n    public let members: [any StackMember]\n\n    public init(@StackBuilder _ content: () -> [any StackMember]) {\n        self.members = content()\n    }\n\n    /// Every member's output, in order.\n    public func score(_ s: DetectionSignals) throws -> [MemberOutput] {\n        try members.compactMap { try $0.score(s) }\n    }\n}\n\n@resultBuilder\npublic enum StackBuilder {\n    public static func buildExpression(_ member: some StackMember) -> [any StackMember] { [member] }\n    public static func buildExpression(_ members: [any StackMember]) -> [any StackMember] { members }\n    public static func buildBlock(_ parts: [any StackMember]...) -> [any StackMember] { parts.flatMap { $0 } }\n    public static func buildOptional(_ part: [any StackMember]?) -> [any StackMember] { part ?? [] }\n    public static func buildEither(first part: [any StackMember]) -> [any StackMember] { part }\n    public static func buildEither(second part: [any StackMember]) -> [any StackMember] { part }\n    public static func buildArray(_ parts: [[any StackMember]]) -> [any StackMember] { parts.flatMap { $0 } }\n}\n"},{"path":"Sources/VeilGardeInference/VeilGardeInference.swift","status":"added","lang":"swift","hunks":[[1,0,1,13]],"header":{"lines":[1,11],"target":"VeilGardeInference","what":[6,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":507,"scopes":[],"old":"","new":"//\n//  VeilGardeInference.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The detector as one pipeline, Decode → Shared Signals → Stack → Revisions → Result: the\n//        signals computed once, a stack of independent members (the screenshot gate and head, the\n//        camera head, the capture signature, the specialist heads, the semantic tiles), the\n//        revisions that read them (the combiner, the frame seam, the preview tail), one\n//        InferenceResult and its schema-v1 JSON. Re-exports the Lens and Core.\n//\n\n@_exported import VeilGardeLens\n"}]};
